<?php session_start(); require __DIR__.'/../config/functions.php'; ensure_install(); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $db=get_db(); if(isset($_POST['register'])){ $app=app_config(); if(empty($app['register_enabled'])) die('注册已关闭'); $pwd=password_hash($_POST['password'],PASSWORD_DEFAULT); $db->prepare('INSERT INTO members(email,phone,password,credits,status,created_at,updated_at) VALUES(?,?,?,?,1,NOW(),NOW())')->execute(array(clean($_POST['email']),clean($_POST['phone']),$pwd,20)); $msg='注册成功，请登录'; } else { $id=clean($_POST['account']); $st=$db->prepare('SELECT * FROM members WHERE (email=? OR phone=?) AND status=1'); $st->execute(array($id,$id)); $u=$st->fetch(); if($u && password_verify($_POST['password'],$u['password'])){$_SESSION['member_id']=$u['id']; header('Location: /user/dashboard.php'); exit;} $msg='登录失败'; }} page_header('会员登录'); ?><div class="grid"><form class="card" method="post"><h2>登录</h2><p class="bad"><?php echo esc($msg); ?></p><input type="hidden" name="csrf" value="<?php echo csrf_token();?>"><label>邮箱/手机号<input name="account"></label><label>密码<input type="password" name="password"></label><button>登录</button></form><form class="card" method="post"><h2>注册</h2><input type="hidden" name="csrf" value="<?php echo csrf_token();?>"><input type="hidden" name="register" value="1"><label>邮箱<input name="email"></label><label>手机号<input name="phone"></label><label>密码<input type="password" name="password"></label><button>注册</button></form></div><?php page_footer(); ?>
